import json,glob
for f in ['Calculation Relay _36','Meridian Free Build','Ravel Free Build']:
 p=next(p for p in glob.glob('/mnt/data/*') if f in p)
 x=json.load(open(p)); print('\n######',f)
 msgs=[]
 for k,v in x['mapping'].items():
  m=v.get('message');
  if not m: continue
  role=m.get('author',{}).get('role'); parts=m.get('content',{}).get('parts',[])
  tt=' '.join(a if isinstance(a,str) else '' for a in parts)
  if role in ('user','assistant') and tt: msgs.append((m.get('create_time') or 0,role,tt))
 print('nmsgs',len(msgs))
 if f=='Calculation Relay _36':
  for _,r,t in msgs:print(r,t[:13000])
 else:
  for _,r,t in sorted(msgs,key=lambda a:a[0])[-17:]:print('\n',r.upper(),t[:850].replace('\n',' '))
