function line3(points,color,width=1,alpha=1){if(points.length<2)return;cx.save();cx.beginPath();for(let i=0;i<points.length;i++){let t=screen(points[i]);if(i===0)cx.moveTo(t.x,t.y);else cx.lineTo(t.x,t.y)}cx.strokeStyle=color;cx.lineWidth=width;cx.globalAlpha=alpha;cx.stroke();cx.restore()}
