function drawScene(p,current){cx.clearRect(0,0,dw,dh);const grad=cx.createRadialGradient(dw*.44,dh*.4,10,dw*.55,dh*.55,dw*.62);grad.addColorStop(0,'#14283b');grad.addColorStop(1,'#0b1827');cx.fillStyle=grad;cx.fillRect(0,0,dw,dh);cx.save();for(let i=0;i<38;i++){const x=(i*97.6180339)%dw,y=(i*41.27182)%dh;cx.fillStyle='rgba(166,193,208,.20)';cx.fillRect(x,y,1,1)}cx.restore();
