function drawPlot(p,current){px.clearRect(0,0,pw,ph);px.fillStyle='#0b1827';px.fillRect(0,0,pw,ph);const size=Math.min(pw,ph),cx0=pw/2,cy0=ph/2,scale=size*.34/Math.max(.6,p.radius);px.strokeStyle='rgba(78,102,124,.4)';px.lineWidth=1;for(let i=-3;i<=3;i++){let a=i*size*.34/3;px.beginPath();px.moveTo(cx0+a,14);px.lineTo(cx0+a,ph-14);px.stroke();px.beginPath();px.moveTo(14,cy0+a);px.lineTo(pw-14,cy0+a);px.stroke()}px.beginPath();px.arc(cx0,cy0,size*.34,0,TAU);px.strokeStyle='#526478';px.setLineDash([3,4]);px.stroke();px.setLineDash([]);px.beginPath();let n=1400,got=false;for(let i=0;i<=n;i++){let t=TAU*i/n;if(t>s.t)break;let v=calc(t,p).v;let x=cx0+v[0]*scale,y=cy0-v[1]*scale;if(!got)px.moveTo(x,y);else px.lineTo(x,y);got=true}px.strokeStyle='#6ce2d3';px.lineWidth=2;px.lineJoin='round';px.stroke();let v=current.v;let x=cx0+v[0]*scale,y=cy0-v[1]*scale;px.beginPath();px.arc(x,y,5,0,TAU);px.fillStyle='#ffca7b';px.fill();px.fillStyle='#9cb4c8';px.font='10px ui-monospace,monospace';px.fillText('Y ↑',10,15);px.fillText('X →',pw-35,ph-10)}
function updateLabels(p,c){const pairs=[['vA',p.freqA.toFixed(2)+'×'],['vB',p.freqB.toFixed(2)+'×'],['vPhase',p.phase.toFixed(2)+' rad'],['vAmp',s.mode===3?p.amp+'°':p.amp+'%'],['vCouple',p.couple.toFixed(2)],['vRadius',p.radius.toFixed(2)]];for(const [k,v] of pairs)$(k).textContent=v;const norm=Math.hypot(...c.v);$('sizeLabel').textContent='|p| = '+norm.toFixed(4);$('aOut').textContent=c.alpha.toFixed(3)+' rad';$('bOut').textContent=c.beta.toFixed(3)+' rad';$('pOut').textContent=c.v.slice(0,3).map(v=>v.toFixed(2)).join(', ');$('wOut').textContent='w = '+c.v[3].toFixed(4);$('tOut').textContent=(s.t/TAU).toFixed(2)}
function draw(){const p=params(),current=calc(s.t,p);drawScene(p,current);drawPlot(p,current);updateLabels(p,current)}
